add_action( 'wp_footer', 'perfectpixel_back_to_top_button' );

function perfectpixel_back_to_top_button() {
	$color = sanitize_hex_color( '{{back_to_top_color}}' );
	?>
	<button type="button" class="perfectpixel-back-to-top" aria-label="<?php echo esc_attr( '{{back_to_top_label}}' ); ?>" style="position:fixed;right:20px;bottom:20px;z-index:9999;width:44px;height:44px;border:0;border-radius:50%;background:<?php echo esc_attr( $color ? $color : '#1d2327' ); ?>;color:#fff;font-size:20px;line-height:44px;cursor:pointer;opacity:0;visibility:hidden;transition:opacity .2s,visibility .2s;box-shadow:0 2px 6px rgba(0,0,0,.25)">&#8593;</button>
	<script>
	( function ( offset ) {
		var btn = document.querySelector( '.perfectpixel-back-to-top' );
		if ( ! btn ) {
			return;
		}
		var toggle = function () {
			var show = window.scrollY > offset;
			btn.style.opacity    = show ? '1' : '0';
			btn.style.visibility = show ? 'visible' : 'hidden';
		};
		window.addEventListener( 'scroll', toggle, { passive: true } );
		btn.addEventListener( 'click', function () {
			window.scrollTo( { top: 0, behavior: window.matchMedia( '(prefers-reduced-motion: reduce)' ).matches ? 'auto' : 'smooth' } );
		} );
		toggle();
	} )( <?php echo (int) '{{back_to_top_offset}}'; ?> );
	</script>
	<?php
}
